/* test_and_set(&lock): devolve o valor antigo e grava 1, tudo de forma atômica */

void enter_region(void) {
	while (test_and_set(&lock) == 1) {
		/* a trava estava ocupada: tenta de novo (espera ocupada) */
	}
}

void leave_region(void) {
	lock = 0;
}

/* test_and_set(&lock): returns the old value and stores 1, all atomically */

void enter_region(void) {
	while (test_and_set(&lock) == 1) {
		/* the lock was taken: try again (busy waiting) */
	}
}

void leave_region(void) {
	lock = 0;
}

